CREATE TABLE IF NOT EXISTS migrations (version TEXT PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password TEXT NOT NULL, platform_admin INTEGER NOT NULL DEFAULT 0 CHECK(platform_admin IN(0,1)), org_id TEXT, preferences TEXT NOT NULL DEFAULT '{}', deleted INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, subscription TEXT NOT NULL DEFAULT 'pilot');
CREATE TABLE communities (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE groups (id TEXT PRIMARY KEY, community_id TEXT NOT NULL REFERENCES communities(id), name TEXT NOT NULL, zone TEXT NOT NULL, chat_id TEXT UNIQUE, allowed INTEGER NOT NULL DEFAULT 0, paused INTEGER NOT NULL DEFAULT 0, settings TEXT NOT NULL DEFAULT '{}');
CREATE TABLE memberships (user_id TEXT NOT NULL REFERENCES users(id), group_id TEXT NOT NULL REFERENCES groups(id), role TEXT NOT NULL CHECK(role IN('member','organizer','group_admin','professional')), active INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(user_id,group_id));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE records (id TEXT PRIMARY KEY, kind TEXT NOT NULL, group_id TEXT NOT NULL REFERENCES groups(id), owner_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, data TEXT NOT NULL CHECK(json_valid(data)), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX records_group_kind ON records(group_id,kind,status);
CREATE INDEX records_owner ON records(owner_id,kind);
CREATE TABLE versions (record_id TEXT NOT NULL REFERENCES records(id) ON DELETE CASCADE, version INTEGER NOT NULL, actor_id TEXT NOT NULL, status TEXT NOT NULL, data TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY(record_id,version));
CREATE TABLE interests (request_id TEXT NOT NULL REFERENCES records(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), active INTEGER NOT NULL, at INTEGER NOT NULL, PRIMARY KEY(request_id,user_id));
CREATE TABLE identities (identity_hash TEXT PRIMARY KEY, provider TEXT NOT NULL, session TEXT NOT NULL, user_id TEXT REFERENCES users(id), verified_at INTEGER, encrypted_ref TEXT);
CREATE UNIQUE INDEX one_identity_per_session ON identities(provider,session,user_id) WHERE user_id IS NOT NULL;
CREATE TABLE link_codes (code_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),group_id TEXT NOT NULL REFERENCES groups(id),expires_at INTEGER NOT NULL,used_at INTEGER);
CREATE TABLE polls (id TEXT PRIMARY KEY REFERENCES records(id) ON DELETE CASCADE, request_id TEXT NOT NULL UNIQUE REFERENCES records(id), provider TEXT NOT NULL, session TEXT NOT NULL, message_id TEXT, options TEXT NOT NULL, multiple INTEGER NOT NULL DEFAULT 0, deadline INTEGER NOT NULL, rules_version INTEGER NOT NULL DEFAULT 1, UNIQUE(provider,session,message_id));
CREATE TABLE votes (poll_id TEXT NOT NULL REFERENCES polls(id) ON DELETE CASCADE, identity_hash TEXT NOT NULL REFERENCES identities(identity_hash), choices TEXT NOT NULL, at INTEGER NOT NULL, event_id TEXT NOT NULL, uncertain INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(poll_id,identity_hash));
CREATE TABLE transitions (record_id TEXT NOT NULL REFERENCES records(id) ON DELETE CASCADE, name TEXT NOT NULL, at INTEGER NOT NULL, PRIMARY KEY(record_id,name));
CREATE TABLE enrollments (id TEXT PRIMARY KEY, record_id TEXT NOT NULL REFERENCES records(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL CHECK(status IN('confirmed','waitlisted','offered','cancelled','reconfirm','completed')), accepted_version INTEGER NOT NULL, seats INTEGER NOT NULL DEFAULT 1 CHECK(seats>0), offered_until INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(record_id,user_id));
CREATE INDEX enrollments_capacity ON enrollments(record_id,status,created_at);
CREATE TABLE progress (cohort_id TEXT NOT NULL REFERENCES records(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),data TEXT NOT NULL,PRIMARY KEY(cohort_id,user_id));
CREATE TABLE challenge_entries (challenge_id TEXT NOT NULL REFERENCES records(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),team TEXT NOT NULL,answers TEXT,points INTEGER,submitted_at INTEGER,visible INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(challenge_id,user_id));
CREATE TABLE inbox (id TEXT PRIMARY KEY,provider TEXT NOT NULL,session TEXT NOT NULL,context TEXT NOT NULL,event_key TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,error TEXT,created_at INTEGER NOT NULL,UNIQUE(provider,session,context,event_key));
CREATE TABLE outbox (id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES groups(id),actor_id TEXT NOT NULL REFERENCES users(id),record_id TEXT REFERENCES records(id),kind TEXT NOT NULL,payload TEXT NOT NULL,status TEXT NOT NULL,mode TEXT NOT NULL,provider_id TEXT,idempotency_key TEXT NOT NULL UNIQUE,due_at INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,error TEXT);
CREATE INDEX outbox_due ON outbox(status,due_at);
CREATE TABLE audit (id TEXT PRIMARY KEY,actor_id TEXT,group_id TEXT,action TEXT NOT NULL,target_id TEXT,at INTEGER NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE feedback (record_id TEXT NOT NULL REFERENCES records(id),user_id TEXT NOT NULL REFERENCES users(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),comment TEXT NOT NULL,PRIMARY KEY(record_id,user_id));
CREATE TABLE reports (id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES groups(id),user_id TEXT NOT NULL REFERENCES users(id),target_id TEXT,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at INTEGER NOT NULL);
CREATE TABLE ai_usage (user_id TEXT NOT NULL,group_id TEXT NOT NULL,day TEXT NOT NULL,calls INTEGER NOT NULL DEFAULT 0,tokens INTEGER NOT NULL DEFAULT 0,latency_ms INTEGER NOT NULL DEFAULT 0,failures INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,group_id,day));
CREATE TABLE payment_orders (id TEXT PRIMARY KEY,enrollment_id TEXT NOT NULL UNIQUE REFERENCES enrollments(id),offer_version INTEGER NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),currency TEXT NOT NULL,beneficiary TEXT NOT NULL,status TEXT NOT NULL,provider_order TEXT UNIQUE,commission_bps INTEGER NOT NULL DEFAULT 0);
CREATE TABLE payment_events (provider TEXT NOT NULL,event_id TEXT NOT NULL,order_id TEXT NOT NULL REFERENCES payment_orders(id),at INTEGER NOT NULL,PRIMARY KEY(provider,event_id));
CREATE TABLE rate_limits (key TEXT PRIMARY KEY,count INTEGER NOT NULL,reset_at INTEGER NOT NULL);
